import { useMotionRuntime } from "@proposalengine/proposal-builder";
import type {
  PageDocumentV3,
  PinSpec,
  Timeline,
  TimelinePlayback,
  TimelineTrack,
} from "@proposalengine/proposal-builder/document";
import { resolveTimelinePlayback } from "@proposalengine/proposal-builder/document";
import { ChevronDown, Diamond, Pause, Play, Plus, Sparkles, X } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { Button, Field, Input } from "./ui";

type Selection = { sectionId: string; blockId: string | null } | null;

type AiPlan = {
  summary: string;
  ops: unknown[];
  diffSummary?: string;
  validationErrors?: string[];
};

export function TimelineSheet({
  open,
  onClose,
  doc,
  selection,
  selectedBlockIds,
  activeTimelineId,
  onChange,
  progress,
  onProgress,
  pageSlug,
  onAiApplied,
}: {
  open: boolean;
  onClose: () => void;
  doc: PageDocumentV3;
  selection: Selection;
  /** Multi-select from right rail / canvas */
  selectedBlockIds: string[];
  activeTimelineId: string | null;
  onChange: (next: PageDocumentV3) => void;
  progress: number;
  onProgress: (p: number) => void;
  pageSlug: string;
  onAiApplied?: (doc: PageDocumentV3) => void;
}) {
  const motion = useMotionRuntime();
  const timelines = doc.timelines ?? [];
  const pins = doc.pins ?? [];
  const [selectedTrack, setSelectedTrack] = useState<number | null>(null);
  const [selectedKf, setSelectedKf] = useState<number | null>(null);
  const scrubbingRef = useRef(false);
  const [aiPrompt, setAiPrompt] = useState("");
  const [aiBusy, setAiBusy] = useState(false);
  const [aiPlan, setAiPlan] = useState<AiPlan | null>(null);
  const [aiErr, setAiErr] = useState<string | null>(null);
  const [aiOpen, setAiOpen] = useState(false);

  const active =
    timelines.find((t) => t.id === activeTimelineId) ?? timelines[0] ?? null;
  const playback: TimelinePlayback = active
    ? resolveTimelinePlayback(active)
    : "manual";

  useEffect(() => {
    if (!open || !active || scrubbingRef.current) return;
    // Preview scrub in editor for any mode; live site uses playback binding.
    motion?.scrubTimeline(active.id, progress);
  }, [open, active, progress, motion]);

  if (!open) return null;

  const focusBlockId = selectedBlockIds[0] ?? selection?.blockId ?? null;

  const updateTimelines = (next: Timeline[]) => {
    onChange({ ...doc, timelines: next });
  };

  const updatePins = (next: PinSpec[]) => {
    onChange({ ...doc, pins: next });
  };

  const patchActive = (patch: Partial<Timeline>) => {
    if (!active) return;
    updateTimelines(timelines.map((t) => (t.id === active.id ? { ...t, ...patch } : t)));
  };

  const addTrackForSelection = (channel: TimelineTrack["channel"] = "opacity") => {
    if (!active || !focusBlockId) return;
    const track: TimelineTrack = {
      id: `tr-${crypto.randomUUID().slice(0, 6)}`,
      blockId: focusBlockId,
      channel,
      keyframes: [
        { t: 0, value: channel === "opacity" ? 0 : channel === "y" ? 40 : 0 },
        { t: 1, value: channel === "opacity" ? 1 : 0 },
      ],
    };
    patchActive({ tracks: [...(active.tracks ?? []), track] });
  };

  const setKeyframeAtPlayhead = () => {
    if (!active || selectedTrack == null) return;
    const tracks = (active.tracks ?? []).slice();
    const track = tracks[selectedTrack];
    if (!track) return;
    const t = Math.round(progress * 200) / 200;
    const kfs = track.keyframes.slice().sort((a, b) => a.t - b.t);
    const existing = kfs.findIndex((k) => Math.abs(k.t - t) < 0.02);
    const value =
      existing >= 0
        ? kfs[existing]!.value
        : (kfs[kfs.length - 1]?.value ?? (track.channel === "opacity" ? 1 : 0));
    if (existing >= 0) {
      kfs[existing] = { ...kfs[existing]!, t, value: Number(value) };
    } else {
      kfs.push({ t, value: Number(value) });
      kfs.sort((a, b) => a.t - b.t);
    }
    tracks[selectedTrack] = { ...track, keyframes: kfs };
    patchActive({ tracks });
  };

  const updateTrack = (index: number, track: TimelineTrack) => {
    if (!active) return;
    const tracks = (active.tracks ?? []).slice();
    tracks[index] = track;
    patchActive({ tracks });
  };

  const removeTrack = (index: number) => {
    if (!active) return;
    patchActive({ tracks: (active.tracks ?? []).filter((_, i) => i !== index) });
  };

  const applyScrub = (v: number) => {
    onProgress(v);
    if (active) motion?.scrubTimeline(active.id, v);
  };

  const addPinForSelection = () => {
    if (!focusBlockId) return;
    updatePins([
      ...pins,
      {
        id: `pin-${crypto.randomUUID().slice(0, 6)}`,
        blockId: focusBlockId,
        start: "top top",
        end: "+=80%",
        pinSpacing: true,
      },
    ]);
  };

  const runAiCompose = async () => {
    if (!aiPrompt.trim()) return;
    setAiBusy(true);
    setAiErr(null);
    setAiPlan(null);
    try {
      const res = await fetch("/api/ai/compose", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          pageSlug,
          prompt: aiPrompt.trim(),
          mode: "motion",
          autoApply: false,
          selection: selection
            ? { sectionId: selection.sectionId, blockId: selection.blockId }
            : undefined,
        }),
      });
      const data = (await res.json()) as {
        error?: string;
        plan?: AiPlan;
        preview?: { diffSummary?: string; validationErrors?: string[] };
      };
      if (!res.ok) throw new Error(data.error || "Compose failed");
      setAiPlan({
        summary: data.plan?.summary || "Proposed changes",
        ops: data.plan?.ops || [],
        diffSummary: data.preview?.diffSummary,
        validationErrors: data.preview?.validationErrors,
      });
    } catch (e) {
      setAiErr(e instanceof Error ? e.message : "AI failed");
    } finally {
      setAiBusy(false);
    }
  };

  const approveAi = async () => {
    if (!aiPlan?.ops?.length) return;
    if (aiPlan.validationErrors?.length) {
      setAiErr(
        `Plan has validation errors — fix or re-plan:\n${aiPlan.validationErrors.slice(0, 4).join("\n")}`
      );
      return;
    }
    setAiBusy(true);
    setAiErr(null);
    try {
      const res = await fetch("/api/ops/apply", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ pageSlug, ops: aiPlan.ops }),
      });
      const data = (await res.json()) as {
        error?: string;
        errors?: string[];
        document?: PageDocumentV3;
      };
      if (!res.ok) {
        const detail = data.errors?.length
          ? data.errors.slice(0, 5).join(" · ")
          : data.error || "Apply failed";
        throw new Error(detail);
      }
      if (data.document) {
        onAiApplied?.(data.document);
        onChange(data.document);
      }
      setAiPlan(null);
      setAiPrompt("");
    } catch (e) {
      setAiErr(e instanceof Error ? e.message : "Apply failed");
    } finally {
      setAiBusy(false);
    }
  };

  return (
    <div className="fk-motion-sheet" role="dialog" aria-label="Keyframe editor">
      <div className="fk-motion-sheet-bar">
        <div className="fk-row" style={{ gap: 10, minWidth: 0 }}>
          <span className="fk-eyebrow">Keyframes</span>
          {active ? (
            <strong style={{ fontSize: 13, overflow: "hidden", textOverflow: "ellipsis" }}>
              {active.name} · {Math.round(progress * 100)}%
            </strong>
          ) : (
            <span className="fk-muted" style={{ fontSize: 12 }}>
              Pick a timeline on the right
            </span>
          )}
          {selectedBlockIds.length > 0 ? (
            <span className="fk-muted" style={{ fontSize: 11 }}>
              {selectedBlockIds.length} block(s)
            </span>
          ) : null}
        </div>
        <div className="fk-row" style={{ gap: 6 }}>
          {active ? (
            <>
              <Button
                size="sm"
                onClick={() => {
                  scrubbingRef.current = false;
                  motion?.playTimeline(active.id);
                  onProgress(0);
                }}
              >
                <Play size={14} />
              </Button>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => {
                  motion?.pauseTimeline(active.id);
                  const p = motion?.getTimelineProgress(active.id);
                  if (typeof p === "number") onProgress(p);
                }}
              >
                <Pause size={14} />
              </Button>
              <label className="fk-row" style={{ gap: 4, fontSize: 11 }}>
                <span className="fk-muted">Play</span>
                <select
                  className="fk-input"
                  style={{ width: "auto", minWidth: 128, padding: "2px 6px", fontSize: 11 }}
                  value={playback}
                  onChange={(e) => {
                    const next = e.target.value as TimelinePlayback;
                    patchActive({
                      playback: next,
                      scrub: next === "scrub",
                    });
                  }}
                >
                  <option value="scrub">Scrub ↔ scroll</option>
                  <option value="play-on-enter">Play on enter</option>
                  <option value="timed">Timed (load)</option>
                  <option value="manual">Manual</option>
                </select>
              </label>
            </>
          ) : null}
          <Button
            size="sm"
            variant={aiOpen ? "primary" : "quiet"}
            onClick={() => setAiOpen((v) => !v)}
          >
            <Sparkles size={14} />
          </Button>
          <Button variant="quiet" size="sm" onClick={onClose} title="Collapse">
            <ChevronDown size={14} />
          </Button>
        </div>
      </div>

      <div className="fk-motion-sheet-body">
        <div className="fk-motion-sheet-col" style={{ flex: 1, minWidth: 0 }}>
          {active ? (
            <>
              <div className="fk-motion-ruler-wrap">
                <div className="fk-motion-ruler-marks">
                  {[0, 0.25, 0.5, 0.75, 1].map((t) => (
                    <span key={t} style={{ left: `${t * 100}%` }}>
                      {Math.round(t * 100)}
                    </span>
                  ))}
                </div>
                <input
                  type="range"
                  min={0}
                  max={1}
                  step={0.005}
                  value={progress}
                  className="fk-motion-ruler"
                  onPointerDown={() => {
                    scrubbingRef.current = true;
                  }}
                  onPointerUp={() => {
                    scrubbingRef.current = false;
                  }}
                  onChange={(e) => applyScrub(Number(e.target.value))}
                />
                <div className="fk-motion-playhead-line" style={{ left: `${progress * 100}%` }} />
              </div>

              <div className="fk-row" style={{ gap: 6, marginBottom: 8, flexWrap: "wrap" }}>
                <Field label="Duration (s)">
                  <Input
                    type="number"
                    min={0.1}
                    step={0.1}
                    value={active.duration ?? 1}
                    onChange={(e) =>
                      patchActive({ duration: Math.max(0.1, Number(e.target.value) || 1) })
                    }
                    style={{ width: 72 }}
                  />
                </Field>
                {playback === "timed" ? (
                  <Field label="Delay (ms)">
                    <Input
                      type="number"
                      min={0}
                      step={50}
                      value={active.delayMs ?? 0}
                      onChange={(e) =>
                        patchActive({
                          delayMs: Math.max(0, Number(e.target.value) || 0),
                        })
                      }
                      style={{ width: 88 }}
                    />
                  </Field>
                ) : null}
                {playback === "timed" || playback === "play-on-enter" || playback === "manual" ? (
                  <Field label="Repeat">
                    <Input
                      type="number"
                      min={-1}
                      step={1}
                      value={active.repeat ?? 0}
                      onChange={(e) => {
                        const n = Number(e.target.value);
                        patchActive({
                          repeat: Number.isFinite(n) ? Math.max(-1, Math.min(500, Math.trunc(n))) : 0,
                        });
                      }}
                      style={{ width: 72 }}
                      title="-1 loops forever"
                    />
                  </Field>
                ) : null}
                {playback === "play-on-enter" || playback === "scrub" ? (
                  <Field label="Scroll start">
                    <Input
                      value={
                        active.scrollStart ||
                        (playback === "play-on-enter" ? "top 80%" : "top top")
                      }
                      onChange={(e) => patchActive({ scrollStart: e.target.value })}
                      placeholder={playback === "play-on-enter" ? "top 80%" : "top top"}
                      style={{ width: 110 }}
                    />
                  </Field>
                ) : null}
                {playback === "scrub" ? (
                  <Field label="Scroll end">
                    <Input
                      value={active.scrollEnd || "bottom bottom"}
                      onChange={(e) => patchActive({ scrollEnd: e.target.value })}
                      placeholder="bottom bottom"
                      style={{ width: 120 }}
                    />
                  </Field>
                ) : null}
              </div>

              <div className="fk-row" style={{ gap: 6, marginBottom: 8, flexWrap: "wrap" }}>
                <Button
                  size="sm"
                  variant="quiet"
                  disabled={!focusBlockId}
                  onClick={() => addTrackForSelection("opacity")}
                >
                  <Plus size={12} /> Opacity
                </Button>
                <Button
                  size="sm"
                  variant="quiet"
                  disabled={!focusBlockId}
                  onClick={() => addTrackForSelection("y")}
                >
                  <Plus size={12} /> Y
                </Button>
                <Button
                  size="sm"
                  variant="quiet"
                  disabled={!focusBlockId}
                  onClick={() => addTrackForSelection("zIndex")}
                >
                  <Plus size={12} /> Z
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  disabled={selectedTrack == null}
                  onClick={setKeyframeAtPlayhead}
                >
                  <Diamond size={12} /> @ playhead
                </Button>
                <Button
                  size="sm"
                  variant="quiet"
                  disabled={!focusBlockId}
                  onClick={addPinForSelection}
                >
                  Pin
                </Button>
                <Field label="Dur">
                  <Input
                    type="number"
                    min={0.1}
                    step={0.1}
                    style={{ width: 64, height: 30 }}
                    value={active.duration}
                    onChange={(e) => patchActive({ duration: Number(e.target.value) || 1 })}
                  />
                </Field>
              </div>

              <div className="fk-motion-lanes">
                {(active.tracks ?? []).map((track, i) => {
                  const hi =
                    selectedBlockIds.includes(track.blockId) ||
                    track.blockId === focusBlockId ||
                    selectedTrack === i;
                  return (
                    <div
                      key={track.id ?? `${track.blockId}-${track.channel}-${i}`}
                      className={`fk-motion-lane${hi ? " is-active" : ""}`}
                      onClick={() => setSelectedTrack(i)}
                    >
                      <div className="fk-motion-lane-label">
                        <span>
                          {track.channel}
                          <span className="fk-muted" style={{ fontWeight: 400, marginLeft: 4 }}>
                            {track.blockId.slice(0, 4)}
                          </span>
                        </span>
                        <button
                          type="button"
                          className="fk-btn fk-btn-quiet fk-btn-sm fk-btn-icon"
                          onClick={(e) => {
                            e.stopPropagation();
                            removeTrack(i);
                          }}
                        >
                          <X size={10} />
                        </button>
                      </div>
                      <div className="fk-motion-lane-track">
                        {track.keyframes.map((kf, ki) => (
                          <button
                            key={`${kf.t}-${ki}`}
                            type="button"
                            className={`fk-motion-kf${selectedTrack === i && selectedKf === ki ? " is-active" : ""}`}
                            style={{ left: `${kf.t * 100}%` }}
                            title={`${kf.t}: ${kf.value}`}
                            onClick={(e) => {
                              e.stopPropagation();
                              setSelectedTrack(i);
                              setSelectedKf(ki);
                            }}
                            onPointerDown={(e) => {
                              e.stopPropagation();
                              const lane = e.currentTarget.parentElement;
                              if (!lane) return;
                              const move = (ev: PointerEvent) => {
                                const rect = lane.getBoundingClientRect();
                                const t = Math.max(
                                  0,
                                  Math.min(1, (ev.clientX - rect.left) / rect.width)
                                );
                                const kfs = track.keyframes.slice();
                                kfs[ki] = { ...kf, t: Math.round(t * 200) / 200 };
                                updateTrack(i, { ...track, keyframes: kfs });
                              };
                              const up = () => {
                                window.removeEventListener("pointermove", move);
                                window.removeEventListener("pointerup", up);
                              };
                              window.addEventListener("pointermove", move);
                              window.addEventListener("pointerup", up);
                            }}
                          />
                        ))}
                      </div>
                    </div>
                  );
                })}
                {!focusBlockId && !(active.tracks ?? []).length ? (
                  <p className="fk-muted" style={{ fontSize: 12 }}>
                    Select blocks on the right or canvas, then Group or add a track.
                  </p>
                ) : null}
              </div>

              {selectedTrack != null && active.tracks?.[selectedTrack] && selectedKf != null ? (
                <div className="fk-row" style={{ gap: 8, marginTop: 8 }}>
                  <Field label="Value">
                    <Input
                      type="number"
                      value={Number(
                        active.tracks[selectedTrack]!.keyframes[selectedKf]?.value ?? 0
                      )}
                      onChange={(e) => {
                        const track = active.tracks![selectedTrack]!;
                        const kfs = track.keyframes.slice();
                        kfs[selectedKf] = {
                          ...kfs[selectedKf]!,
                          value: Number(e.target.value),
                        };
                        updateTrack(selectedTrack, { ...track, keyframes: kfs });
                      }}
                    />
                  </Field>
                </div>
              ) : null}

              {pins.length > 0 ? (
                <div style={{ marginTop: 8 }}>
                  <span className="fk-eyebrow">Pins</span>
                  {pins.map((p, i) => (
                    <div key={p.id ?? i} className="fk-row" style={{ gap: 6, fontSize: 11 }}>
                      <span className="fk-muted">
                        {p.blockId?.slice(0, 8) || p.sectionId?.slice(0, 8)}
                      </span>
                      <Button
                        size="sm"
                        variant="quiet"
                        onClick={() => updatePins(pins.filter((_, j) => j !== i))}
                      >
                        <X size={10} />
                      </Button>
                    </div>
                  ))}
                </div>
              ) : null}
            </>
          ) : (
            <p className="fk-muted" style={{ fontSize: 12, padding: 8 }}>
              Create or select a timeline in the right rail.
            </p>
          )}
        </div>

        {aiOpen ? (
          <div className="fk-motion-sheet-col fk-motion-ai-col">
            <span className="fk-eyebrow">AI</span>
            <textarea
              className="fk-textarea"
              style={{ minHeight: 64, fontSize: 12, marginTop: 6 }}
              placeholder="e.g. Slow the fade…"
              value={aiPrompt}
              onChange={(e) => setAiPrompt(e.target.value)}
            />
            <div className="fk-row" style={{ gap: 6, marginTop: 6 }}>
              <Button
                size="sm"
                disabled={aiBusy || !aiPrompt.trim()}
                onClick={() => void runAiCompose()}
              >
                Plan
              </Button>
              {aiPlan ? (
                <>
                  <Button
                    size="sm"
                    disabled={aiBusy || Boolean(aiPlan.validationErrors?.length)}
                    onClick={() => void approveAi()}
                  >
                    Approve
                  </Button>
                  <Button size="sm" variant="ghost" onClick={() => setAiPlan(null)}>
                    Reject
                  </Button>
                </>
              ) : null}
            </div>
            {aiPlan ? (
              <div className="fk-panel" style={{ padding: 8, marginTop: 8, fontSize: 12 }}>
                <strong>{aiPlan.summary}</strong>
                <p className="fk-muted" style={{ margin: "4px 0" }}>
                  {aiPlan.ops.length} op(s)
                  {aiPlan.diffSummary ? ` · ${aiPlan.diffSummary}` : ""}
                </p>
                {aiPlan.validationErrors?.length ? (
                  <p className="fk-err" style={{ margin: "6px 0 0", whiteSpace: "pre-wrap" }}>
                    {aiPlan.validationErrors.slice(0, 5).join("\n")}
                  </p>
                ) : (
                  <p className="fk-muted" style={{ margin: "4px 0 0", color: "#86efac" }}>
                    Preview OK — Approve to apply
                  </p>
                )}
              </div>
            ) : null}
            {aiErr ? <p className="fk-err">{aiErr}</p> : null}
          </div>
        ) : null}
      </div>
    </div>
  );
}
