import { useCallback, useEffect, useState } from "react";
import { api } from "./api";
import { SectionHeader } from "./AdminShell";
import { Button, Field, Input, Panel, Textarea } from "./ui";

type FieldDef = {
  key: string;
  label: string;
  type: string;
  required?: boolean;
};

type Collection = {
  id: string;
  slug: string;
  name: string;
  fields: FieldDef[];
};

type Preset = {
  id: string;
  name: string;
  slug: string;
  description: string;
  fields: FieldDef[];
};

type Item = {
  id: string;
  slug: string;
  status: string;
  data: Record<string, unknown>;
  sort: number;
};

export function ContentPanel() {
  const [collections, setCollections] = useState<Collection[]>([]);
  const [presets, setPresets] = useState<Preset[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [items, setItems] = useState<Item[]>([]);
  const [view, setView] = useState<"list" | "new" | "items" | "edit-item">("list");
  const [msg, setMsg] = useState<string | null>(null);
  const [itemDraft, setItemDraft] = useState<Record<string, string>>({});
  const [itemStatus, setItemStatus] = useState<"draft" | "published">("draft");
  const [editingItemId, setEditingItemId] = useState<string | null>(null);

  const selected = collections.find((c) => c.id === selectedId) || null;

  const loadCollections = useCallback(async () => {
    const data = await api<{ collections: Collection[] }>("/api/collections");
    setCollections(data.collections || []);
  }, []);

  useEffect(() => {
    void (async () => {
      try {
        const [c, p] = await Promise.all([
          api<{ collections: Collection[] }>("/api/collections"),
          api<{ presets: Preset[] }>("/api/collections/presets"),
        ]);
        setCollections(c.collections || []);
        setPresets(p.presets || []);
      } catch (e) {
        setMsg(e instanceof Error ? e.message : "Failed to load");
      }
    })();
  }, []);

  const openCollection = async (id: string) => {
    setSelectedId(id);
    setView("items");
    setMsg(null);
    const data = await api<{ items: Item[] }>(`/api/collections/${encodeURIComponent(id)}/items`);
    setItems(data.items || []);
  };

  const createFromPreset = async (presetId: string) => {
    setMsg(null);
    const preset = presets.find((p) => p.id === presetId);
    const res = await api<{ collection: Collection }>("/api/collections", {
      method: "POST",
      body: JSON.stringify({ presetId, name: preset?.name || "" }),
    });
    await loadCollections();
    setView("list");
    if (res.collection?.id) void openCollection(res.collection.id);
  };

  const startNewItem = () => {
    setEditingItemId(null);
    setItemStatus("draft");
    const draft: Record<string, string> = {};
    for (const f of selected?.fields || []) draft[f.key] = "";
    setItemDraft(draft);
    setView("edit-item");
  };

  const saveItem = async () => {
    if (!selected) return;
    setMsg(null);
    const data: Record<string, unknown> = {};
    for (const f of selected.fields) {
      const raw = itemDraft[f.key] ?? "";
      if (f.type === "number") data[f.key] = raw === "" ? null : Number(raw);
      else if (f.type === "boolean") data[f.key] = raw === "true" || raw === "1";
      else if (f.type === "tags")
        data[f.key] = raw
          .split(",")
          .map((s) => s.trim())
          .filter(Boolean);
      else data[f.key] = raw;
    }
    if (editingItemId) {
      await api(`/api/collections/${selected.id}/items/${editingItemId}`, {
        method: "PATCH",
        body: JSON.stringify({ status: itemStatus, data }),
      });
    } else {
      await api(`/api/collections/${selected.id}/items`, {
        method: "POST",
        body: JSON.stringify({ status: itemStatus, data }),
      });
    }
    await openCollection(selected.id);
  };

  if (view === "new") {
    return (
      <div>
        <SectionHeader
          title="New collection"
          description="Pick a preset — you can edit fields later."
          actions={
            <Button size="sm" variant="ghost" onClick={() => setView("list")}>
              Back
            </Button>
          }
        />
        <div
          style={{
            padding: 20,
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))",
            gap: 12,
          }}
        >
          {presets.map((p) => (
            <button
              key={p.id}
              type="button"
              className="fk-panel"
              style={{
                padding: 16,
                textAlign: "left",
                cursor: "pointer",
                border: "1px solid var(--border)",
                background: "var(--fk-panel)",
              }}
              onClick={() => void createFromPreset(p.id)}
            >
              <strong style={{ display: "block", fontSize: 14 }}>{p.name}</strong>
              <span className="fk-muted" style={{ fontSize: 12, marginTop: 6, display: "block" }}>
                {p.description}
              </span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  if (view === "edit-item" && selected) {
    return (
      <div>
        <SectionHeader
          title={editingItemId ? "Edit item" : "New item"}
          description={selected.name}
          actions={
            <div className="fk-row" style={{ gap: 8 }}>
              <Button size="sm" variant="ghost" onClick={() => void openCollection(selected.id)}>
                Cancel
              </Button>
              <Button size="sm" onClick={() => void saveItem()}>
                Save
              </Button>
            </div>
          }
        />
        <div style={{ padding: 20, maxWidth: 560, display: "flex", flexDirection: "column", gap: 12 }}>
          <Field label="Status">
            <select
              className="fk-input"
              value={itemStatus}
              onChange={(e) => setItemStatus(e.target.value as "draft" | "published")}
            >
              <option value="draft">Draft</option>
              <option value="published">Published</option>
            </select>
          </Field>
          {selected.fields.map((f) => (
            <Field key={f.key} label={f.label + (f.required ? " *" : "")}>
              {f.type === "richtext" ? (
                <Textarea
                  rows={5}
                  value={itemDraft[f.key] || ""}
                  onChange={(e) => setItemDraft((d) => ({ ...d, [f.key]: e.target.value }))}
                />
              ) : (
                <Input
                  type={f.type === "number" ? "number" : f.type === "date" ? "date" : "text"}
                  value={itemDraft[f.key] || ""}
                  onChange={(e) => setItemDraft((d) => ({ ...d, [f.key]: e.target.value }))}
                  placeholder={f.type === "tags" ? "tag1, tag2" : undefined}
                />
              )}
            </Field>
          ))}
        </div>
      </div>
    );
  }

  if (view === "items" && selected) {
    return (
      <div>
        <SectionHeader
          title={selected.name}
          description={`/${selected.slug} · ${selected.fields.length} fields`}
          actions={
            <div className="fk-row" style={{ gap: 8 }}>
              <Button size="sm" variant="ghost" onClick={() => setView("list")}>
                All collections
              </Button>
              <Button size="sm" onClick={startNewItem}>
                Add item
              </Button>
            </div>
          }
        />
        <div style={{ padding: 20 }}>
          {items.length === 0 ? (
            <div className="fk-empty">
              <p className="fk-title" style={{ fontSize: "1.1rem" }}>
                No items yet
              </p>
              <p className="fk-muted" style={{ marginTop: 8 }}>
                Add your first {selected.name.toLowerCase()} entry.
              </p>
              <Button size="sm" style={{ marginTop: 16 }} onClick={startNewItem}>
                Add item
              </Button>
            </div>
          ) : (
            <Panel>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
                <thead>
                  <tr className="fk-muted" style={{ textAlign: "left" }}>
                    <th style={{ padding: "10px 12px" }}>Item</th>
                    <th style={{ padding: "10px 12px" }}>Status</th>
                    <th style={{ padding: "10px 12px" }} />
                  </tr>
                </thead>
                <tbody>
                  {items.map((item) => {
                    const label = String(
                      item.data.title ?? item.data.name ?? item.data.author ?? item.slug
                    );
                    return (
                      <tr key={item.id} style={{ borderTop: "1px solid var(--border)" }}>
                        <td style={{ padding: "10px 12px" }}>{label}</td>
                        <td style={{ padding: "10px 12px" }}>{item.status}</td>
                        <td style={{ padding: "10px 12px", textAlign: "right" }}>
                          <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => {
                              setEditingItemId(item.id);
                              setItemStatus(item.status === "published" ? "published" : "draft");
                              const draft: Record<string, string> = {};
                              for (const f of selected.fields) {
                                const v = item.data[f.key];
                                draft[f.key] = Array.isArray(v)
                                  ? v.join(", ")
                                  : v == null
                                    ? ""
                                    : String(v);
                              }
                              setItemDraft(draft);
                              setView("edit-item");
                            }}
                          >
                            Edit
                          </Button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </Panel>
          )}
        </div>
      </div>
    );
  }

  return (
    <div>
      <SectionHeader
        title="Content"
        description="Collections power blogs, products, team pages, and more."
        actions={
          <Button size="sm" onClick={() => setView("new")}>
            New collection
          </Button>
        }
      />
      <div style={{ padding: 20 }}>
        {msg ? <p className="fk-muted">{msg}</p> : null}
        {collections.length === 0 ? (
          <div className="fk-empty">
            <p className="fk-title" style={{ fontSize: "1.1rem" }}>
              No collections yet
            </p>
            <p className="fk-muted" style={{ marginTop: 8 }}>
              Start with Blog, Products, Projects, Team, or a blank schema.
            </p>
            <Button size="sm" style={{ marginTop: 16 }} onClick={() => setView("new")}>
              Add collection
            </Button>
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {collections.map((c) => (
              <button
                key={c.id}
                type="button"
                className="fk-panel"
                style={{
                  padding: "14px 16px",
                  textAlign: "left",
                  cursor: "pointer",
                  border: "1px solid var(--border)",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
                onClick={() => void openCollection(c.id)}
              >
                <span>
                  <strong style={{ fontSize: 14 }}>{c.name}</strong>
                  <span className="fk-muted" style={{ marginLeft: 10, fontSize: 12 }}>
                    /{c.slug}
                  </span>
                </span>
                <span className="fk-muted" style={{ fontSize: 12 }}>
                  {c.fields.length} fields
                </span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
