import {
  MotionRuntimeProvider,
  ProposalDocument,
  SiteCanvasPreviewProvider,
} from "@proposalengine/proposal-builder";
import type { PageDocumentV3 } from "@proposalengine/proposal-builder/document";
import type { MotionLink } from "@proposalengine/proposal-builder/document";
import { useMemo } from "react";
import { DEFAULT_FOOTER, DEFAULT_NAVBAR, type FooterSettings, type NavbarSettings } from "./document";

function hrefForSlug(slug: string): string {
  if (slug === "home" || slug === "") return "/";
  return `/${encodeURIComponent(slug)}`;
}

const MAX_WIDTH: Record<string, number> = {
  sm: 640,
  md: 768,
  lg: 1024,
  xl: 1280,
  "2xl": 1536,
  "6xl": 1152,
  full: 1600,
};

function pageHasImmersiveScene3D(doc: PageDocumentV3): boolean {
  return (doc.pages ?? []).some((section) =>
    (section.blocks ?? []).some(
      (b) =>
        b.type === "Scene3D" &&
        Boolean((b.props as { immersive?: boolean } | undefined)?.immersive)
    )
  );
}

export function PublicSiteView({
  doc,
  pages,
  currentSlug,
  navbar,
  footer,
}: {
  doc: PageDocumentV3;
  pages: Array<{ slug: string; title: string }>;
  currentSlug: string;
  navbar: NavbarSettings | null;
  footer?: FooterSettings | null;
}) {
  const nav = { ...DEFAULT_NAVBAR, ...(navbar || {}) };
  const foot = { ...DEFAULT_FOOTER, ...(footer || {}) };
  const brand = (nav.brand ?? "My Site").trim() || "My Site";
  const sticky = nav.sticky !== false;
  const bg = nav.bgColor?.trim() || "#141416";
  const text = nav.textColor?.trim() || "#f4f4f5";
  const accent = nav.accentColor?.trim() || "#ea580c";
  const padY = typeof nav.paddingY === "number" ? nav.paddingY : 14;
  const padX = typeof nav.paddingX === "number" ? nav.paddingX : 20;
  const maxW = MAX_WIDTH[nav.maxWidth || "6xl"] ?? 1100;
  const border = nav.borderBottom !== false;
  const ctaLabel = (nav.ctaLabel || "").trim();
  const ctaHref = (nav.ctaHref || "").trim();

  const immersive3d = useMemo(() => pageHasImmersiveScene3D(doc), [doc]);

  const linksByBlockId = useMemo(() => {
    const map = new Map<string, MotionLink[]>();
    for (const section of doc.pages ?? []) {
      for (const block of section.blocks ?? []) {
        if (block.links?.length) map.set(block.id, block.links);
      }
    }
    return map;
  }, [doc.pages]);

  const hasMotion =
    (doc.timelines && doc.timelines.length > 0) || linksByBlockId.size > 0;

  const canvas = (
    <ProposalDocument
      sections={doc.pages}
      sectionBackgroundOverrides={doc.pageBackgroundOverrides}
      proposalSurfaceDefaults={doc.templateSurfaceDefaults}
      proposalAnimationDefaults={doc.templateAnimationDefaults}
      timelines={doc.timelines}
      previewInteractive={false}
      layoutMode="website"
    />
  );

  return (
    <div
      data-finnsk-immersive-page={immersive3d ? "1" : undefined}
      style={{
        minHeight: "100dvh",
        height: immersive3d ? "100dvh" : undefined,
        overflow: immersive3d ? "hidden" : undefined,
        background: "#0c0c0d",
        color: "#f4f4f5",
        display: "flex",
        flexDirection: "column",
      }}
    >
      <a
        href="#site-document"
        className="fk-muted"
        style={{
          position: "absolute",
          left: -9999,
        }}
      >
        Skip to content
      </a>
      <header
        data-finnsk-site-navbar="1"
        style={{
          position: immersive3d ? "fixed" : sticky ? "sticky" : "relative",
          top: 0,
          left: 0,
          right: 0,
          zIndex: 40,
          background: immersive3d || nav.overlay ? "transparent" : bg,
          borderBottom:
            immersive3d || !border ? "none" : `1px solid ${accent}33`,
          padding: `${padY}px ${padX}px`,
          backdropFilter:
            !immersive3d && nav.variant === "glass"
              ? `blur(${nav.glassBlur ?? 12}px)`
              : undefined,
          pointerEvents: "none",
        }}
      >
        <div
          style={{
            maxWidth: immersive3d ? "none" : maxW,
            margin: "0 auto",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 24,
            pointerEvents: "auto",
          }}
        >
          <a
            href="/"
            style={{
              color: text,
              textDecoration: "none",
              fontWeight: 600,
              fontSize: 14,
              textShadow: immersive3d ? "0 1px 8px rgba(0,0,0,0.65)" : undefined,
            }}
          >
            {brand}
          </a>
          <nav aria-label="Primary" style={{ display: "flex", flexWrap: "wrap", gap: 4, alignItems: "center" }}>
            {pages.map((p) => {
              const active = p.slug === currentSlug;
              return (
                <a
                  key={p.slug}
                  href={hrefForSlug(p.slug)}
                  aria-current={active ? "page" : undefined}
                  style={{
                    padding: "6px 10px",
                    textDecoration: "none",
                    fontSize: 13,
                    fontWeight: active ? 600 : 500,
                    color: active ? accent : text,
                    opacity: active ? 1 : 0.72,
                    textShadow: immersive3d
                      ? "0 1px 8px rgba(0,0,0,0.65)"
                      : undefined,
                    borderBottom:
                      nav.activeStyle === "underline" && active
                        ? `2px solid ${accent}`
                        : "2px solid transparent",
                  }}
                >
                  {p.title}
                </a>
              );
            })}
            {ctaLabel && ctaHref ? (
              <a
                href={ctaHref}
                style={{
                  marginLeft: 8,
                  padding: "8px 14px",
                  background: accent,
                  color: "#fff",
                  textDecoration: "none",
                  fontSize: 13,
                  fontWeight: 600,
                }}
              >
                {ctaLabel}
              </a>
            ) : null}
          </nav>
        </div>
      </header>
      <div
        id="site-document"
        style={{
          background: immersive3d ? "#0c0c0d" : "#fff",
          color: immersive3d ? "#f4f4f5" : "#111",
          minHeight: immersive3d ? "100dvh" : undefined,
          height: immersive3d ? "100dvh" : undefined,
          flex: immersive3d ? undefined : 1,
        }}
      >
        {hasMotion ? (
          <SiteCanvasPreviewProvider>
            <MotionRuntimeProvider
              timelines={doc.timelines}
              linksByBlockId={linksByBlockId}
              pins={doc.pins}
            >
              {canvas}
            </MotionRuntimeProvider>
          </SiteCanvasPreviewProvider>
        ) : (
          canvas
        )}
      </div>
      {!immersive3d && foot.enabled !== false ? (
        <footer
          style={{
            background: foot.bgColor || "#0c0c0d",
            color: foot.textColor || "#a1a1aa",
            padding: "32px 20px",
            borderTop: "1px solid #27272a",
          }}
        >
          <div style={{ maxWidth: maxW, margin: "0 auto", fontSize: 13 }}>
            <p style={{ margin: 0 }}>{foot.copyright || `© ${brand}`}</p>
          </div>
        </footer>
      ) : null}
    </div>
  );
}
