import { useEffect, useState } from "react";
import { api } from "./api";
import { SectionHeader } from "./AdminShell";
import { Button, Field, Input, Panel, Textarea } from "./ui";

export function SettingsPanel({
  aiModelDraft,
  setAiModelDraft,
  aiKeyDraft,
  setAiKeyDraft,
  aiKeySet,
  mcpToken,
  onSaveAi,
  onRotateMcp,
  aiMsg,
}: {
  aiModelDraft: string;
  setAiModelDraft: (v: string) => void;
  aiKeyDraft: string;
  setAiKeyDraft: (v: string) => void;
  aiKeySet: boolean;
  mcpToken: string;
  onSaveAi: () => void;
  onRotateMcp: () => void;
  aiMsg: string | null;
}) {
  const [customCss, setCustomCss] = useState("");
  const [customJsHead, setCustomJsHead] = useState("");
  const [customJsBody, setCustomJsBody] = useState("");
  const [jsEnabled, setJsEnabled] = useState(false);
  const [unsplashKey, setUnsplashKey] = useState("");
  const [pexelsKey, setPexelsKey] = useState("");
  const [msg, setMsg] = useState<string | null>(null);

  useEffect(() => {
    void (async () => {
      try {
        const data = await api<{
          settings: {
            customCss?: string;
            customCode?: { enabled?: boolean; head?: string; body?: string };
            assets?: { unsplashKeySet?: boolean; pexelsKeySet?: boolean };
          };
        }>("/api/settings");
        setCustomCss(String(data.settings?.customCss || ""));
        setJsEnabled(Boolean(data.settings?.customCode?.enabled));
        setCustomJsHead(String(data.settings?.customCode?.head || ""));
        setCustomJsBody(String(data.settings?.customCode?.body || ""));
      } catch {
        /* ignore */
      }
    })();
  }, []);

  const saveAdvanced = async () => {
    setMsg(null);
    const cur = await api<{ settings: Record<string, unknown> }>("/api/settings");
    const prevAssets = (cur.settings.assets || {}) as Record<string, unknown>;
    const assets: Record<string, unknown> = { ...prevAssets };
    if (unsplashKey.trim()) assets.unsplashKey = unsplashKey.trim();
    if (pexelsKey.trim()) assets.pexelsKey = pexelsKey.trim();
    await api("/api/settings", {
      method: "PUT",
      body: JSON.stringify({
        settings: {
          ...cur.settings,
          customCss,
          customCode: {
            enabled: jsEnabled,
            head: customJsHead,
            body: customJsBody,
          },
          assets,
        },
      }),
    });
    setUnsplashKey("");
    setPexelsKey("");
    setMsg("Settings saved.");
  };

  const origin = typeof location !== "undefined" ? location.origin : "https://YOUR.workers.dev";

  return (
    <div>
      <SectionHeader
        title="Settings"
        description="AI, MCP connection, asset providers, and advanced code."
      />
      <div style={{ padding: 20, maxWidth: 560, display: "flex", flexDirection: "column", gap: 20 }}>
        <Panel>
          <div style={{ padding: 16, display: "flex", flexDirection: "column", gap: 12 }}>
            <div className="fk-eyebrow">AI</div>
            <Field label="Provider">
              <Input value="gemini" disabled />
            </Field>
            <Field label="Model">
              <Input
                value={aiModelDraft}
                onChange={(e) => setAiModelDraft(e.target.value)}
                placeholder="gemini-2.5-flash"
                list="fk-gemini-models"
              />
              <datalist id="fk-gemini-models">
                <option value="gemini-2.5-flash" />
                <option value="gemini-2.0-flash" />
                <option value="gemini-2.5-flash-lite" />
              </datalist>
            </Field>
            <Field label={aiKeySet ? "Gemini API key (leave blank to keep)" : "Gemini API key"}>
              <Input
                type="password"
                value={aiKeyDraft}
                onChange={(e) => setAiKeyDraft(e.target.value)}
                placeholder={aiKeySet ? "•••••••• (set)" : "AIza…"}
                autoComplete="off"
              />
            </Field>
            <Button size="sm" onClick={onSaveAi}>
              Save AI
            </Button>
            {aiMsg ? <p className="fk-muted">{aiMsg}</p> : null}
          </div>
        </Panel>

        <Panel>
          <div style={{ padding: 16, display: "flex", flexDirection: "column", gap: 12 }}>
            <div className="fk-eyebrow">Connect Cursor / Claude</div>
            <p className="fk-muted" style={{ margin: 0, fontSize: 13 }}>
              MCP URL: <code>{origin}/mcp</code>
            </p>
            <div className="fk-row" style={{ gap: 8 }}>
              <Button size="sm" variant="ghost" onClick={onRotateMcp}>
                {mcpToken ? "Rotate token" : "Create token"}
              </Button>
            </div>
            {mcpToken ? (
              <Field label="Bearer token">
                <Input readOnly value={mcpToken} onFocus={(e) => e.currentTarget.select()} />
              </Field>
            ) : (
              <p className="fk-muted" style={{ fontSize: 12, margin: 0 }}>
                Create a token, then paste it into your MCP client. Full setup lives in the repo docs.
              </p>
            )}
          </div>
        </Panel>

        <Panel>
          <div style={{ padding: 16, display: "flex", flexDirection: "column", gap: 12 }}>
            <div className="fk-eyebrow">Asset providers (optional)</div>
            <Field label="Unsplash access key">
              <Input
                type="password"
                value={unsplashKey}
                onChange={(e) => setUnsplashKey(e.target.value)}
                placeholder="Leave blank to keep"
                autoComplete="off"
              />
            </Field>
            <Field label="Pexels API key">
              <Input
                type="password"
                value={pexelsKey}
                onChange={(e) => setPexelsKey(e.target.value)}
                placeholder="Leave blank to keep"
                autoComplete="off"
              />
            </Field>
          </div>
        </Panel>

        <Panel>
          <div style={{ padding: 16, display: "flex", flexDirection: "column", gap: 12 }}>
            <div className="fk-eyebrow">Custom CSS</div>
            <Field label="Site CSS">
              <Textarea
                rows={6}
                value={customCss}
                onChange={(e) => setCustomCss(e.target.value)}
                placeholder="/* Public site styles */"
              />
            </Field>
          </div>
        </Panel>

        <Panel>
          <div style={{ padding: 16, display: "flex", flexDirection: "column", gap: 12 }}>
            <div className="fk-eyebrow">Advanced — custom JavaScript</div>
            <p className="fk-muted" style={{ margin: 0, fontSize: 12 }}>
              Can read cookies and break the site. Owner-only. Prefer Embed blocks when possible.
            </p>
            <label className="fk-row" style={{ gap: 8, fontSize: 13 }}>
              <input
                type="checkbox"
                checked={jsEnabled}
                onChange={(e) => setJsEnabled(e.target.checked)}
              />
              Enable custom JS snippets
            </label>
            <Field label="Head snippet">
              <Textarea
                rows={4}
                value={customJsHead}
                onChange={(e) => setCustomJsHead(e.target.value)}
                disabled={!jsEnabled}
              />
            </Field>
            <Field label="End of body snippet">
              <Textarea
                rows={4}
                value={customJsBody}
                onChange={(e) => setCustomJsBody(e.target.value)}
                disabled={!jsEnabled}
              />
            </Field>
          </div>
        </Panel>

        <Button size="sm" onClick={() => void saveAdvanced()}>
          Save advanced settings
        </Button>
        {msg ? <p className="fk-muted">{msg}</p> : null}
      </div>
    </div>
  );
}
