import {
  migratePageDocumentV3ToV2,
  PAGE_V3_SCHEMA_VERSION,
  safeParsePageDocument,
  type PageDocumentV3,
  type PageV2,
} from "@proposalengine/proposal-builder/document";

export function parseBlockPropsJson(raw: string | Record<string, unknown>): unknown {
  if (typeof raw === "string") {
    try {
      return JSON.parse(raw) as unknown;
    } catch {
      return null;
    }
  }
  return raw;
}

export function extractPageDocumentV3(
  blocks: Array<{ component_type: string; props_json: string | Record<string, unknown> }>
): PageDocumentV3 | null {
  const root = blocks.find((b) => b.component_type === "ProposalDocument");
  if (!root) return null;
  const props = parseBlockPropsJson(root.props_json);
  const parsed = safeParsePageDocument(props);
  if (!parsed.success) return null;
  return parsed.data;
}

export function toEditorPage(doc: PageDocumentV3): PageV2 {
  return migratePageDocumentV3ToV2(doc);
}

export function fromEditorPage(v2: PageV2, prev: PageDocumentV3 | null): PageDocumentV3 {
  return {
    schemaVersion: PAGE_V3_SCHEMA_VERSION,
    pages: v2.sections,
    pageBackgroundOverrides: v2.sectionBackgroundOverrides,
    templateSurfaceDefaults: prev?.templateSurfaceDefaults ?? v2.proposalSurfaceDefaults,
    templateAnimationDefaults: prev?.templateAnimationDefaults ?? v2.proposalAnimationDefaults,
    timelines: v2.timelines ?? prev?.timelines,
    pins: v2.pins ?? prev?.pins,
  };
}

