import { useCallback, useEffect, useState } from "react";
import { api } from "./api";
import { SectionHeader } from "./AdminShell";
import { Button, Field, Input, Panel, Textarea } from "./ui";

type AuditIssue = {
  id: string;
  severity: string;
  pageSlug?: string;
  message: string;
  fixHint: string;
};

type Audit = {
  score: number;
  rank: string;
  issues: AuditIssue[];
};

export function SeoPanel() {
  const [audit, setAudit] = useState<Audit | null>(null);
  const [siteTitle, setSiteTitle] = useState("");
  const [siteDesc, setSiteDesc] = useState("");
  const [ogImage, setOgImage] = useState("");
  const [msg, setMsg] = useState<string | null>(null);

  const runAudit = useCallback(async () => {
    const data = await api<{ audit: Audit }>("/api/seo/audit");
    setAudit(data.audit);
  }, []);

  useEffect(() => {
    void (async () => {
      try {
        const s = await api<{
          settings: { seo?: { metaTitle?: string; metaDescription?: string; ogImage?: string } };
        }>("/api/settings");
        setSiteTitle(s.settings?.seo?.metaTitle || "");
        setSiteDesc(s.settings?.seo?.metaDescription || "");
        setOgImage(s.settings?.seo?.ogImage || "");
        await runAudit();
      } catch (e) {
        setMsg(e instanceof Error ? e.message : "Failed to load SEO");
      }
    })();
  }, [runAudit]);

  const saveSiteSeo = async () => {
    setMsg(null);
    const cur = await api<{ settings: Record<string, unknown> }>("/api/settings");
    await api("/api/settings", {
      method: "PUT",
      body: JSON.stringify({
        settings: {
          ...cur.settings,
          seo: {
            metaTitle: siteTitle.trim(),
            metaDescription: siteDesc.trim(),
            ogImage: ogImage.trim(),
          },
        },
      }),
    });
    setMsg("Saved site SEO defaults.");
    await runAudit();
  };

  return (
    <div>
      <SectionHeader
        title="SEO"
        description="Site-wide defaults and health audit for search and AI crawlers."
        actions={
          <div className="fk-row" style={{ gap: 8 }}>
            <Button size="sm" variant="ghost" onClick={() => void runAudit()}>
              Re-run audit
            </Button>
            <Button size="sm" onClick={() => void saveSiteSeo()}>
              Save defaults
            </Button>
          </div>
        }
      />
      <div style={{ padding: 20, maxWidth: 720, display: "flex", flexDirection: "column", gap: 16 }}>
        {audit ? (
          <Panel>
            <div style={{ padding: 16, display: "flex", alignItems: "center", gap: 20 }}>
              <div>
                <div className="fk-eyebrow">Rank</div>
                <div style={{ fontSize: 42, fontWeight: 700, lineHeight: 1, color: "var(--fk-orange)" }}>
                  {audit.rank}
                </div>
              </div>
              <div>
                <div className="fk-eyebrow">Score</div>
                <div style={{ fontSize: 28, fontWeight: 600 }}>{audit.score}/100</div>
                <p className="fk-muted" style={{ margin: "4px 0 0", fontSize: 12 }}>
                  {audit.issues.length} issue{audit.issues.length === 1 ? "" : "s"}
                </p>
              </div>
            </div>
          </Panel>
        ) : null}

        <Panel>
          <div style={{ padding: 16, display: "flex", flexDirection: "column", gap: 12 }}>
            <Field label="Default meta title">
              <Input value={siteTitle} onChange={(e) => setSiteTitle(e.target.value)} />
            </Field>
            <Field label="Default meta description">
              <Textarea rows={3} value={siteDesc} onChange={(e) => setSiteDesc(e.target.value)} />
            </Field>
            <Field label="Default Open Graph image URL">
              <Input value={ogImage} onChange={(e) => setOgImage(e.target.value)} />
            </Field>
          </div>
        </Panel>

        {audit && audit.issues.length > 0 ? (
          <Panel>
            <div style={{ padding: 16 }}>
              <div className="fk-eyebrow" style={{ marginBottom: 10 }}>
                Issues
              </div>
              <ul style={{ margin: 0, padding: 0, listStyle: "none" }}>
                {audit.issues.map((issue) => (
                  <li
                    key={issue.id}
                    style={{
                      padding: "10px 0",
                      borderTop: "1px solid var(--border)",
                      fontSize: 13,
                    }}
                  >
                    <strong style={{ textTransform: "uppercase", fontSize: 10, opacity: 0.7 }}>
                      {issue.severity}
                    </strong>
                    <div style={{ marginTop: 4 }}>{issue.message}</div>
                    <div className="fk-muted" style={{ marginTop: 4, fontSize: 12 }}>
                      {issue.fixHint}
                      {issue.pageSlug ? ` · ${issue.pageSlug}` : ""}
                    </div>
                  </li>
                ))}
              </ul>
            </div>
          </Panel>
        ) : null}

        {msg ? <p className="fk-muted">{msg}</p> : null}
      </div>
    </div>
  );
}
