import type { ButtonHTMLAttributes, InputHTMLAttributes, ReactNode, TextareaHTMLAttributes } from "react";

export function Button({
  variant = "primary",
  size = "md",
  className = "",
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: "primary" | "ghost" | "quiet";
  size?: "md" | "sm" | "icon" | "icon-sm";
}) {
  const v =
    variant === "ghost" ? "fk-btn-ghost" : variant === "quiet" ? "fk-btn-quiet" : "fk-btn-primary";
  const s =
    size === "sm"
      ? "fk-btn-sm"
      : size === "icon"
        ? "fk-btn-icon"
        : size === "icon-sm"
          ? "fk-btn-sm fk-btn-icon"
          : "";
  return <button type="button" className={`fk-btn ${v} ${s} ${className}`.trim()} {...props} />;
}

export function Input(props: InputHTMLAttributes<HTMLInputElement>) {
  return <input className="fk-input" {...props} />;
}

export function Textarea(props: TextareaHTMLAttributes<HTMLTextAreaElement>) {
  return <textarea className="fk-textarea" {...props} />;
}

export function Field({
  label,
  children,
}: {
  label: string;
  children: ReactNode;
}) {
  return (
    <div className="fk-field">
      <label className="fk-label">{label}</label>
      {children}
    </div>
  );
}

export function Panel({
  children,
  className = "",
}: {
  children: ReactNode;
  className?: string;
}) {
  return <div className={`fk-panel ${className}`.trim()}>{children}</div>;
}
