import type { PageDocumentV3, Timeline } from "@proposalengine/proposal-builder/document";
import { Layers, Plus, Sparkles, X } from "lucide-react";
import { Button } from "./ui";

export type MotionBlockRef = { sectionId: string; blockId: string };

function blockLabel(
  doc: PageDocumentV3,
  sectionId: string,
  blockId: string
): { type: string; preview: string } {
  const sec = doc.pages?.find((p) => p.id === sectionId);
  const block = sec?.blocks?.find((b) => b.id === blockId);
  if (!block) return { type: "?", preview: blockId.slice(0, 6) };
  const props = (block.props || {}) as Record<string, unknown>;
  let preview = "";
  if (typeof props.html === "string") {
    preview = props.html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim().slice(0, 28);
  } else if (typeof props.alt === "string") {
    preview = props.alt.slice(0, 28);
  }
  return { type: block.type, preview: preview || blockId.slice(0, 8) };
}

export function MotionRightRail({
  doc,
  timelines,
  activeTimelineId,
  onSelectTimeline,
  onCreateTimeline,
  selectedBlocks,
  onToggleBlock,
  onClearSelection,
  onAddGroupToTimeline,
  onMakeCutout,
  onClose,
}: {
  doc: PageDocumentV3;
  timelines: Timeline[];
  activeTimelineId: string | null;
  onSelectTimeline: (id: string) => void;
  onCreateTimeline: () => void;
  selectedBlocks: MotionBlockRef[];
  onToggleBlock: (ref: MotionBlockRef, additive: boolean) => void;
  onClearSelection: () => void;
  onAddGroupToTimeline: (channel?: string) => void;
  onMakeCutout?: () => void;
  onClose: () => void;
}) {
  const sections = doc.pages ?? [];
  const selectedSet = new Set(selectedBlocks.map((b) => b.blockId));

  return (
    <aside className="fk-motion-right" aria-label="Motion blocks and timelines">
      <div className="fk-motion-right-head">
        <span className="fk-eyebrow">Motion</span>
        <Button variant="quiet" size="sm" className="fk-btn-icon" onClick={onClose} title="Close">
          <X size={14} />
        </Button>
      </div>

      <div className="fk-motion-right-section">
        <div className="fk-row" style={{ justifyContent: "space-between", marginBottom: 6 }}>
          <span className="fk-eyebrow">Timelines</span>
          <Button variant="quiet" size="sm" onClick={onCreateTimeline} title="New timeline">
            <Plus size={12} />
          </Button>
        </div>
        <div className="fk-motion-right-list">
          {timelines.length === 0 ? (
            <p className="fk-muted" style={{ fontSize: 11, margin: 0 }}>
              No timelines yet.
            </p>
          ) : (
            timelines.map((t) => (
              <button
                key={t.id}
                type="button"
                className={`fk-motion-right-item${t.id === activeTimelineId ? " is-active" : ""}`}
                onClick={() => onSelectTimeline(t.id)}
              >
                <span className="fk-motion-right-item-title">{t.name}</span>
                <span className="fk-muted" style={{ fontSize: 10 }}>
                  {t.tracks?.length ?? 0} tracks
                  {t.scrub ? " · scrub" : ""}
                </span>
              </button>
            ))
          )}
        </div>
      </div>

      <div className="fk-motion-right-section" style={{ flex: 1, minHeight: 0 }}>
        <div className="fk-row" style={{ justifyContent: "space-between", marginBottom: 6 }}>
          <span className="fk-eyebrow">
            <Layers size={10} style={{ display: "inline", marginRight: 4 }} />
            Blocks
          </span>
          {selectedBlocks.length > 0 ? (
            <button type="button" className="fk-btn fk-btn-quiet fk-btn-sm" onClick={onClearSelection}>
              Clear
            </button>
          ) : null}
        </div>
        <p className="fk-muted" style={{ fontSize: 10, margin: "0 0 6px" }}>
          Click · Shift+click multi · or select on canvas
        </p>
        <div className="fk-motion-right-list" style={{ flex: 1, overflow: "auto" }}>
          {sections.map((sec, si) => (
            <div key={sec.id} style={{ marginBottom: 8 }}>
              <div className="fk-motion-right-sec-label">S{si + 1}</div>
              {(sec.blocks ?? []).map((block) => {
                const meta = blockLabel(doc, sec.id, block.id);
                const on = selectedSet.has(block.id);
                return (
                  <button
                    key={block.id}
                    type="button"
                    className={`fk-motion-right-item${on ? " is-active" : ""}`}
                    onClick={(e) =>
                      onToggleBlock(
                        { sectionId: sec.id, blockId: block.id },
                        e.shiftKey || e.metaKey || e.ctrlKey
                      )
                    }
                  >
                    <span className="fk-motion-right-item-title">
                      {meta.type}
                      {on ? " ✓" : ""}
                    </span>
                    <span className="fk-muted" style={{ fontSize: 10 }}>
                      {meta.preview}
                    </span>
                  </button>
                );
              })}
              {(sec.blocks ?? []).length === 0 ? (
                <p className="fk-muted" style={{ fontSize: 10, margin: "2px 0 0 4px" }}>
                  Empty
                </p>
              ) : null}
            </div>
          ))}
        </div>
      </div>

      <div className="fk-motion-right-foot">
        <p className="fk-muted" style={{ fontSize: 10, margin: "0 0 6px" }}>
          {selectedBlocks.length
            ? `${selectedBlocks.length} selected`
            : "Select blocks to group"}
        </p>
        <Button
          size="sm"
          disabled={!selectedBlocks.length}
          onClick={() => onAddGroupToTimeline("opacity")}
          style={{ width: "100%", marginBottom: 4 }}
        >
          <Sparkles size={12} /> Group → opacity
        </Button>
        <Button
          size="sm"
          variant="ghost"
          disabled={!selectedBlocks.length}
          onClick={() => onAddGroupToTimeline("y")}
          style={{ width: "100%", marginBottom: 4 }}
        >
          Group → Y scrub
        </Button>
        <Button
          size="sm"
          variant="ghost"
          disabled={!selectedBlocks.length || !onMakeCutout}
          onClick={() => onMakeCutout?.()}
          style={{ width: "100%" }}
          title="Strip frame/shadow for transparent PNGs"
        >
          Make cutout (transparent)
        </Button>
      </div>
    </aside>
  );
}
